/* @lc app=leetcode id=3367 lang=kotlin */ class Solution { fun maximizeSumOfWeights(edges: Array<IntArray>, k: Int): Long = (edges.size + 1).let { n -> edges.flatMap { (a, b, w) -> listOf(a to (b to w), b to (a to w)) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> LongArray(n).let { d0 -> LongArray(n).let { d1 -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { (v, _) -> par[v] == -1 }.map { (v, _) -> v.also { par[v] = u } } }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().forEach { v -> g[v].orEmpty().filter { (c, _) -> par[c] == v && c != 0 }.let { ch -> ch.sumOf { d0[it.first] }.let { base -> ch.map { (c, w) -> d1[c] + w - d0[c] }.filter { it > 0 }.sortedDescending().let { gains -> d0[v] = base + gains.take(k).sum() }.also { d1[v] = base + ch.map { (c, w) -> d1[c] + w - d0[c] }.filter { it > 0 }.sortedDescending().take(k - 1).sum() } } } }.let { d0[0] } } } } } } }